const e=[{id:"proj-artistry",slug:"artistry-gold-diamonds",title:"Artistry Gold & Diamonds",subtitle:"Crafting a Premium Digital Jewellery Shopping Experience.",serviceId:"web-development",serviceName:"Web Development",category:"E-commerce Development",industry:"Jewellery & Luxury Retail",isDemonstrationOrPrototype:!0,statusBadge:"Verified Live Production Platform",thumbnail:"/images/projects/artistry-homepage.png",heroImage:"/images/projects/artistry-homepage.png",shortDescription:"A premium jewellery e-commerce experience built for modern gold and diamond retail.",overview:"Established in 1998, Artistry Gold & Diamonds is a premier fine jewellery brand and concept store network operating over 40 physical boutiques across India alongside a high-performance digital flagship. The platform connects generations of authentic Indian karigar craftsmanship with modern e-commerce convenience, featuring 100% BIS-hallmarked 22K and 18K gold, HUID verification, certified natural diamonds, real-time commodity gold rate tickers, and bespoke design studio services.",challenge:"Luxury jewellery retail demands an uncompromising digital presentation where customers expect certified authenticity, real-time gold market pricing, intricate high-resolution product inspection, and seamless shopping cart experiences across mobile and desktop devices without performance degradation.",solution:"Architected a full-stack MERN (React.js, Node.js, Express.js, MongoDB) platform featuring responsive component-driven layouts, a live 22K gold rate ticker with BIS 916 Hallmark verification badges, structured product categorization across Gold, Diamonds, and Gemstones, persistent shopping bag workflows, and instant customer service connectivity.",architectureHighlights:["React.js single-page application with responsive, high-DPI jewellery product showcases and fluid motion transitions","Dynamic 22K gold rate integration displaying daily market valuation and BIS hallmark trust credentials","MongoDB document schemas optimized for multifaceted jewellery attributes (carats, gross/net weight, purity, certified stones)","Modular Node.js & Express RESTful API with cached catalogue retrieval, search indexing, and resilient order workflows","Persistent shopping bag and wishlist state management across customer sessions with zero layout shift"],engineeringCapabilitiesDemonstrated:["Full-stack MERN architecture with clean separation of presentation, business logic, and persistence layers","Luxury brand UI/UX execution utilizing Cormorant Garamond headings, Jost typography, and rose-gold blush aesthetics","Mobile-first responsive design ensuring tactile browsing across smartphones, tablets, and desktop displays","E-commerce trust architecture integrating HUID hallmark badges, customer inquiries, and secure checkout endpoints"],technologies:["React.js","Node.js","MongoDB","JavaScript","Tailwind CSS","Framer Motion","Express.js"],resultsOrProjections:[{metric:"22K Live",label:"Gold Rate Ticker",detail:"Real-time market rate synchronization with BIS hallmark assurance"},{metric:"100%",label:"Mobile Ergonomics",detail:"Touch-optimized navigation, product zoom, and drawer interactions"},{metric:"< 1.2s",label:"Catalogue Page Load",detail:"Optimized image pipelines and component code splitting"}],galleryImages:["/images/projects/artistry-homepage.png","/images/projects/artistry-catalogue.png","/images/projects/artistry-gold-coins.png"],demoUrl:"https://www.artistrygoldanddiamonds.shop/",liveUrl:"https://www.artistrygoldanddiamonds.shop/",seoTitle:"Artistry Gold & Diamonds | Jewellery E-commerce Project | Peace Haven",seoDescription:"Explore Artistry Gold & Diamonds, a premium jewellery e-commerce website developed using React.js, Node.js and MongoDB by Peace Haven.",implementedFeatures:[{title:"Live 22K Gold Rate Ticker",description:"Real-time daily gold rate banner with direct BIS 916 Hallmark transparency guarantee.",tag:"Market Integration"},{title:"Comprehensive Jewellery Catalogue",description:"Structured categorization spanning Gold, Diamonds, Gemstones, Rings, Bangles, Necklaces, and Mangalsutras.",tag:"Catalogue Architecture"},{title:"Curated Bridal & Heritage Collections",description:"Specialized showcases for Wedding edits, Festive collections, Daily Wear, and Custom design inquiries.",tag:"Merchandising"},{title:"Interactive Shopping Bag & Wishlist",description:"Sliding drawer cart with instant quantity adjustments, persistent local storage, and transparent item pricing.",tag:"E-commerce Core"},{title:"Search & Category Filtering",description:"Instant product filtering by purity (22K, 18K), jewellery category, design style, and pricing tier.",tag:"Navigation UX"},{title:"Customer Authentication & Profiles",description:"Secure user login, order tracking status, profile management, and saved shipping preferences.",tag:"User System"},{title:"Real-Time Customer Assistance",description:'Integrated direct "Ask Us" live chat support and physical showroom store locator.',tag:"Support"},{title:"Trust & Authenticity Assurances",description:"Explicit badges for 100% BIS Hallmarked HUID gold, certified natural diamonds, and lifetime exchange policy.",tag:"Trust Badges"},{title:"Mobile-First Responsive Layout",description:"Fluid touch navigation, gesture-friendly product carousels, and optimized layout shifts across all devices.",tag:"Performance"}],publishedAt:"2026-02-15"},{id:"proj-clinic",slug:"peace-haven-clinic",title:"Peace Haven Clinic Website",subtitle:"An integrated digital clinic experience designed to simplify patient appointments and healthcare administration.",serviceId:"web-development",serviceName:"Web Development",category:"Clinical Web Development",industry:"Medical & Clinical Practice",isDemonstrationOrPrototype:!0,statusBadge:"Verified Live Production Platform",thumbnail:"/images/projects/clinic-homepage.png",heroImage:"/images/projects/clinic-homepage.png",shortDescription:"A modern healthcare platform featuring online appointments, doctor workflows and clinic management capabilities.",overview:"A modern clinic website and appointment management platform designed to simplify the interaction between patients, doctors and clinic administrators. The platform provides a professional online presence for the clinic, allowing patients to explore available services, access doctor information and interact with the appointment booking system. The system also includes dedicated interfaces and workflows for doctors, patients and administrative staff, subject to the functionality verified in the implementation.",challenge:"Modern outpatient healthcare practices often struggle with disconnected appointment booking systems, manual telephone coordination, patient registration friction, and administrative delays in routing consultation requests between clinical departments and consulting physicians.",solution:"Architected and engineered a comprehensive, responsive clinic web application using React.js, Vite, Node.js, Express.js, and MongoDB. The platform provides a welcoming patient-facing portal with direct doctor credential exploration, multi-department service categorization, slot-based online appointment reservation, Google OAuth authentication, and an administrative doctor management interface.",architectureHighlights:["React.js single-page application built with Vite for instantaneous HMR, optimized asset code-splitting, and smooth client-side routing","Express.js RESTful API architecture connecting patient appointment requests with backend scheduling and slot management","MongoDB document schemas structuring doctor profiles, medical specialties, operating hours, and patient appointment records","Unified authentication subsystem supporting Google OAuth (Google Sign-In) and protected role-based staff routes","Staff and Doctor management interfaces (/admin/doctors) allowing administrative oversight of consultation slots and clinical availability"],engineeringCapabilitiesDemonstrated:["Full-stack healthcare web architecture separating client presentation, REST routing, and persistence tiers","Responsive healthcare design system utilizing deep charcoal navy, warm off-white, and muted teal accents","Appointment workflow engineering handling consultation modes (in-person and virtual teleconsultation)","Digital health privacy compliance ensuring zero leakage of identifiable patient records or unverified diagnostic claims"],technologies:["React.js","Vite","Node.js","Express.js","MongoDB","JavaScript"],resultsOrProjections:[{metric:"100%",label:"Digital Appointment Booking",detail:"Direct patient self-service booking eliminating telephone scheduling friction"},{metric:"Vite + React",label:"Modern Frontend Stack",detail:"Rapid sub-second page transitions and responsive cross-device layout"},{metric:"24/7",label:"Emergency & Clinic Connectivity",detail:"Continuous helpline routing, doctor credential exploration, and service accessibility"}],galleryImages:["/images/projects/clinic-homepage.png","/images/projects/clinic-appointment-booking.png","/images/projects/clinic-doctors.png","/images/projects/clinic-services.png","/images/projects/clinic-portal-login.png"],demoUrl:"https://peacehaven.clinic/",liveUrl:"https://peacehaven.clinic/",seoTitle:"Peace Haven Clinic Website | Healthcare Web Development | Peace Haven",seoDescription:"Explore the Peace Haven Clinic website, a healthcare web development project featuring a modern patient experience and appointment management platform built with React, Node.js and MongoDB.",implementedFeatures:[{title:"Online Appointment Booking",description:"Interactive appointment scheduling allowing patients to select consultation date and appointment slots for clinic visits.",tag:"Patient Experience"},{title:"Google OAuth & User Authentication",description:"Seamless patient and staff login supporting Google OAuth (gsi/client) and secure email credentials.",tag:"Authentication"},{title:"Doctor & Department Directory",description:"Comprehensive listing of clinic physicians, medical degrees, specializations, and departmental profiles.",tag:"Clinical Directory"},{title:"In-Person & Teleconsultation Options",description:"Flexible consultation options enabling patients to book on-premise clinic visits or virtual medical teleconsultations.",tag:"Consultation Workflow"},{title:"Doctor Admin Management",description:"Dedicated administrative interface (/admin/doctors) allowing staff to oversee physician availability, roster schedules, and department listings.",tag:"Staff & Admin"},{title:"Emergency Care & 24/7 Helpline",description:"Direct one-tap telephone connectivity to clinic emergency triage and ambulance assistance (+91 9360599560).",tag:"Emergency Care"},{title:"Comprehensive Medical Specialties",description:"Detailed information and care guides spanning General Medicine, Diabetes & Hypertension, Infectious Diseases, and Geriatric Care.",tag:"Specialties"},{title:"Mobile-Optimized Patient Portal",description:"Fully responsive mobile-first interface ensuring patients can easily schedule visits from any smartphone or tablet.",tag:"Responsive UX"}],technicalArchitecture:{layers:[{layer:"Frontend",technology:"React.js",purpose:"User interface"},{layer:"Build Tool",technology:"Vite",purpose:"Development and production builds"},{layer:"Backend",technology:"Node.js",purpose:"Server-side application"},{layer:"Framework",technology:"Express.js",purpose:"API and routing"},{layer:"Database",technology:"MongoDB",purpose:"Application data"},{layer:"Language",technology:"JavaScript",purpose:"Application development"}],flowDiagram:["Patient / Doctor / Admin","React Frontend","Express.js REST API","Node.js Backend","MongoDB Database"]},developmentProcess:[{step:"01",title:"Requirement Analysis",description:"Stakeholder discovery defining patient booking journeys, physician scheduling constraints, and staff management workflows."},{step:"02",title:"UI/UX Design",description:"Designing high-trust clinical interfaces, accessible color contrasts, and ergonomic appointment booking modals."},{step:"03",title:"Frontend Development",description:"Building responsive React components with Vite, Plus Jakarta Sans typography, and fluid route transitions."},{step:"04",title:"Backend API Development",description:"Architecting Node.js and Express RESTful endpoints for appointment slots, doctor profiles, and authentication."},{step:"05",title:"Database Integration",description:"Structuring MongoDB document schemas for flexible clinical departments, physician profiles, and booking records."},{step:"06",title:"Authentication & Role Management",description:"Implementing Google OAuth sign-in, token handling, and protected administrative routes for clinic staff."},{step:"07",title:"Appointment Workflow Development",description:"Engineering slot availability checks, booking confirmations, and consultation mode selections."},{step:"08",title:"Testing & Deployment",description:"End-to-end user flow testing, mobile viewport verification, production build optimization, and cloud deployment."}],liveCta:{heading:"Experience the Clinic Platform",description:"Explore the digital healthcare experience developed by Peace Haven.",buttonLabel:"Visit Live Website"},publishedAt:"2026-03-01"},{id:"proj-ai-command-center",slug:"ai-command-center",title:"AI Command Center",subtitle:"An AI-powered digital platform developed to centralize intelligent capabilities and support modern business workflows.",serviceId:"fintech",serviceName:"FinTech Solutions",category:"AI & Enterprise Technology",industry:"Financial Technology & AI Platforms",isDemonstrationOrPrototype:!0,statusBadge:"Verified Live Production Platform",thumbnail:"/images/projects/ai-command-center-dashboard.png",heroImage:"/images/projects/ai-command-center-dashboard.png",shortDescription:"An intelligent digital platform designed to centralize AI-powered capabilities and simplify supported business workflows.",overview:"AI Command Center is an intelligent digital platform developed by Peace Haven to bring AI-powered capabilities into a unified application environment. The platform is designed to provide a centralized interface for accessing and managing its available AI capabilities, helping users interact with intelligent tools and streamline supported digital workflows.",challenge:"Modern enterprise operations and corporate finance teams face operational fragmentation across disconnected banking portals, disparate mailbox threads, unstructured invoice documents, and standalone AI models. Without centralized intelligence, financial reconciliation stalls, auto-debits risk going unmonitored, and multi-agent coordination remains disjointed.",solution:"Peace Haven engineered AI Command Center as a unified, role-governed operational platform integrating real-time banking telemetry via Plaid API, automated email payment stream triage with Google Workspace, document intelligence via OpenAI API, and specialized AI agents for multi-channel business execution.",architectureHighlights:["Multi-bank financial bridge powered by Plaid API, aggregating commercial checking, yield reserve, and term loan facilities with real-time balance tracking","Automated mailbox payment ingestion pipeline extracting lender statements, auto-debits, and supplier invoices directly into ledger reconciliation queues","Context-aware multi-agent workspace with conversational query dispatcher, automated thread summarization, and executive weekly briefing generation","Enterprise role-based access control (RBAC) isolating sensitive liquidity ledgers and bank accounts under privileged Finance User permissions"],engineeringCapabilitiesDemonstrated:["Full-stack enterprise application engineering in React 19, TypeScript, Vite, and Node.js with dark/light theme switching","Financial API integration including Plaid Link token negotiation, institution webhook handling, and transaction synchronization","Natural language document processing pipelines parsing PDF invoices, bills of lading, NAICS codes, and payment terms via OpenAI API","Operational claim resolution workflows validating fleet and insurance payout confirmations with cryptographic audit stamps"],technologies:["React 19","TypeScript","Node.js","Plaid API","OpenAI API","Tailwind CSS","Vite","Google Workspace API"],resultsOrProjections:[{metric:"100%",label:"Plaid Bank Sync",detail:"Real-time multi-account balance monitoring across commercial checking and credit facilities"},{metric:"< 15s",label:"Payment Ingestion Triage",detail:"Automated invoice and auto-debit extraction from corporate mailboxes to ledger queues"},{metric:"Zero Drift",label:"Financial Reconciliation",detail:"Defensible audit trails with role-scoped Finance User data isolation"}],galleryImages:["/images/projects/ai-command-center-dashboard.png","/images/projects/ai-command-center-finance.png","/images/projects/ai-command-center-mail.png","/images/projects/ai-command-center-agents.png","/images/projects/ai-command-center-login-dark.png"],demoUrl:"https://ai.peacehavencorp.com/",liveUrl:"https://ai.peacehavencorp.com/",seoTitle:"AI Command Center | AI-Powered Technology Platform | Peace Haven",seoDescription:"Explore AI Command Center, an intelligent digital platform developed by Peace Haven. Discover its verified AI capabilities, technology architecture and business applications.",implementedFeatures:[{title:"Plaid Multi-Bank Aggregation",description:"Direct financial connection via Plaid API aggregating commercial checking, treasury cash reserves, and term liabilities with continuous balance tracking.",tag:"FinTech Banking"},{title:"Automated Payment Stream Triage",description:"Smart extraction of incoming billing, lender notices, and trade invoices from Google Workspace mailboxes, matching payments directly to ledger accounts.",tag:"Financial Automation"},{title:"Loan & Auto-Debit Amortization",description:"Automated monitoring of recurring commercial equipment loans and interest obligations, verifying scheduled auto-debits against lender confirmations.",tag:"Debt & Treasury"},{title:"Claims & Payout Resolution",description:"Dedicated operational workflows validating fleet damage claims and insurance reimbursements with direct payout credit authorizations.",tag:"Operational FinTech"},{title:"AI Mail & Thread Synthesis",description:"Real-time synchronization of executive and finance mailboxes with automated AI thread summaries, action item extraction, and smart reply drafts.",tag:"AI Workspace"},{title:"Multi-Agent Task Board",description:"Interactive Kanban board orchestrating specialized AI agents across research, briefings, attention flags, and document compliance checks.",tag:"Agent Orchestration"},{title:"Document & Trade Parsing",description:"Deep ingestion of PDF bills, international trade documents, and Word specs, extracting vendor identities, NAICS codes, and net payment terms.",tag:"Document Intelligence"},{title:"Role-Scoped Governance & RBAC",description:"Granular access controls isolating sensitive bank accounts and liquidity balances exclusively to authorized Finance User credentials.",tag:"Enterprise Security"}],technicalArchitecture:{layers:[{layer:"Presentation Layer",technology:"React 19.3 & Tailwind CSS",purpose:"Responsive executive dashboard, dark/light theme switching, and real-time interface components"},{layer:"Build & Bundling",technology:"Vite 5",purpose:"Rapid HMR, optimized ESM code splitting, and production bundle minification"},{layer:"API & Orchestration",technology:"Node.js & Express REST",purpose:"Microservices routing, token handling, session tracking, and background connector sync"},{layer:"Financial Rail Gateway",technology:"Plaid API",purpose:"Link token creation, multi-institution account aggregation, and transaction stream sync"},{layer:"Intelligence Engine",technology:"OpenAI API Models",purpose:"Document semantic extraction, email thread synthesis, and contextual agent reasoning"},{layer:"Workspace Connectors",technology:"Google Workspace APIs",purpose:"Continuous Gmail mailbox ingestion, Google Docs parsing, and Drive asset synchronization"}],flowDiagram:["Executive / Finance Director Interface","React 19 Client SPA (Vite)","Node.js & Express Application Gateway","Plaid Financial API (Bank Sync) & OpenAI Engine","Reconciled Financial Ledger & Document Store"]},developmentProcess:[{step:"01",title:"System Discovery & Scope",description:"Identifying multi-entity operational bottlenecks across commercial banking, lender debits, and email communication streams."},{step:"02",title:"UI/UX Architecture",description:"Crafting high-density dark mode executive dashboards in Inter typography with accessible contrasts and color-coded status pills."},{step:"03",title:"Financial Rail Integration",description:"Implementing Plaid Link token exchange, webhook listeners, account balance polling, and transaction ledger schemas."},{step:"04",title:"AI Document Pipelines",description:"Engineering prompt extraction templates and PDF/Word parser pipelines to capture structured invoice entities with high confidence."},{step:"05",title:"Payment Triage Logic",description:"Building heuristic matching rules connecting incoming mailbox notices with scheduled bank account debits and loan amortizations."},{step:"06",title:"RBAC & Token Security",description:"Implementing JWT bearer authorization, refresh token rotation, and Finance User permission barriers for sensitive accounts."},{step:"07",title:"Multi-Agent Board",description:"Developing the interactive attention queue and task Kanban board for rapid operator triage of flagged documents and claims."},{step:"08",title:"Production Hardening",description:"Full viewport verification, network resilience testing, audit log verification, and live cloud deployment to ai.peacehavencorp.com."}],liveCta:{heading:"Explore AI Command Center",description:"Experience the AI-powered platform developed by Peace Haven.",buttonLabel:"Visit Live Project"},publishedAt:"2026-03-15"},{id:"proj-ph-google",slug:"ph-google",title:"PH Google",subtitle:"Centralized Digital Workspace",serviceId:"fintech",serviceName:"FinTech Solutions",category:"Enterprise Web Application",industry:"Business Productivity & Enterprise Technology",isDemonstrationOrPrototype:!0,statusBadge:"Internal Project",thumbnail:"/images/projects/ph-google/ph-google-hero.png",heroImage:"/images/projects/ph-google/ph-google-hero.png",shortDescription:"A unified enterprise workspace bringing essential business tools, documents and team collaboration into one centralized platform.",overview:"PH Google is a centralized digital workspace platform developed to simplify and streamline everyday business activities for Peace Haven employees. The platform provides a unified environment where users can access and manage essential business tools, documents, files and organizational resources from a single interface. It integrates workplace services such as Google Drive, Gmail, Google Calendar and Google Sheets to simplify information sharing, communication and collaboration. Employees can organize files, manage documents, access important business information, coordinate meetings and collaborate with their teams. The platform also provides centralized user management, role-based access, notifications and administrative controls to support efficient workplace operations. By bringing multiple workplace services together into one unified environment, PH Google aims to reduce application switching, improve team productivity, simplify workflows and create a smarter digital workplace.",challenge:"Enterprise operational teams frequently experience severe workflow fragmentation and application switching fatigue across disparate browser tabs, isolated email inboxes, unlinked calendar schedules, and disconnected document folders. Without a centralized hub, employees lose valuable hours locating shared spreadsheets, coordinating departmental reviews, and managing user access permissions across siloed corporate services.",solution:"Peace Haven engineered PH Google as a unified digital workspace application combining a responsive, ergonomic React.js frontend with a robust Python backend service. The platform integrates core Google Workspace services (Drive, Gmail, Calendar, Sheets) through centralized OAuth token negotiation, provides real-time departmental notifications, and enforces granular role-based access control (RBAC) across employee accounts.",architectureHighlights:["React.js single-page application delivering an ergonomic, high-density corporate dashboard with instant service navigation","Python backend service orchestrating Google Workspace API integrations, session tokens, and security policies","Unified Google Drive and Sheets federation with direct document previews and departmental access scoping","Centralized employee directory and role-based access control (RBAC) isolating sensitive administrative functions"],engineeringCapabilitiesDemonstrated:["Full-stack enterprise application engineering in React.js and Python with RESTful service orchestration","OAuth 2.0 service account authentication flow with automatic token rotation and scope segregation","Real-time workplace notification pipelines tracking document updates, meeting invites, and role changes","High-contrast corporate UI/UX designed in accordance with Peace Haven branding standards"],technologies:["React.js","Python","Google Services Integration","RESTful API","Tailwind CSS"],resultsOrProjections:[{metric:"100%",label:"Workspace Federation",detail:"Single sign-on access across Google Drive, Gmail, Calendar & Sheets"},{metric:"4-in-1",label:"Service Unification",detail:"Integrated documents, email threads, team schedules & data sheets"},{metric:"Zero Drift",label:"Access Control",detail:"Centralized RBAC administration with complete session audit logging"}],galleryImages:["/images/projects/ph-google/ph-google-hero.png","/images/projects/ph-google/ph-google-gmail.webp","/images/projects/ph-google/ph-google-user-management.webp","/images/projects/ph-google/ph-google-admin.webp","/images/projects/ph-google/ph-google-notifications.webp"],seoTitle:"PH Google | Enterprise Productivity Platform | Peace Haven",seoDescription:"Discover PH Google, Peace Haven's internal digital workspace platform developed with React.js and Python to centralize workplace tools, documents and collaboration.",implementedFeatures:[{title:"Unified Digital Workspace",description:"Centralized access to essential business tools, organizational resources, and team workflows from a single ergonomic interface.",tag:"Workspace Core"},{title:"Google Services Integration",description:"Seamless connectivity to Google Drive, Gmail, Google Calendar, and Google Sheets, simplifying information sharing and collaboration.",tag:"Service Federation"},{title:"Document & File Management",description:"Comprehensive file organization, document preview, and business resource management across shared departmental folders.",tag:"Drive & Docs"},{title:"Team Collaboration & Comms",description:"Integrated email workspace, meeting coordination, and collaborative workflows reducing context switching.",tag:"Collaboration"},{title:"Centralized User Management",description:"Employee account administration, granular role-based access control (RBAC), and session security oversight.",tag:"Identity & Access"},{title:"Notifications & Administration",description:"Workplace event stream, system health telemetry, API quota allocation, and administrative governance controls.",tag:"Governance"}],technicalArchitecture:{layers:[{layer:"Presentation Layer",technology:"React.js & Tailwind CSS",purpose:"Unified digital workspace interface, responsive service dock, and interactive dashboards"},{layer:"Application Backend",technology:"Python Backend Services",purpose:"Server-side application logic, Google OAuth token exchange, and API request routing"},{layer:"Workplace Integration Rail",technology:"Google Services Integration",purpose:"Federated connectivity to Google Drive, Gmail, Calendar, and Sheets APIs"},{layer:"Access & Governance",technology:"Centralized User Directory & RBAC",purpose:"Role-based access permissions, employee account provisioning, and audit logs"}],flowDiagram:["Peace Haven Employee / Admin","React.js Digital Workspace SPA","Python Application Backend (REST API)","Google Workspace Services (Drive, Gmail, Calendar, Sheets)","Secure Enterprise File & Directory Store"]},developmentProcess:[{step:"01",title:"Business Requirement Analysis",description:"Auditing internal Peace Haven operational workflows and identifying application switching bottlenecks."},{step:"02",title:"Workspace Architecture Planning",description:"Defining the unified React.js frontend interface and Python backend service boundaries."},{step:"03",title:"UI/UX Development",description:"Designing ergonomic dark mode dashboards, high-contrast typography, and intuitive service cards."},{step:"04",title:"Frontend Development",description:"Building the component hierarchy, navigation sidebar, document previews, and responsive layouts."},{step:"05",title:"Python Backend Development",description:"Implementing server-side business logic, REST API routing, and session token management."},{step:"06",title:"Google Services Integration",description:"Connecting Google Drive, Gmail, Google Calendar, and Google Sheets through secure authentication."},{step:"07",title:"User Management & Access Control",description:"Engineering role-based permissions (RBAC), employee provisioning, and security audit trails."},{step:"08",title:"Testing and Validation",description:"Conducting comprehensive cross-device responsiveness, accessibility, and end-to-end integration tests."}],publishedAt:"2026-04-10"},{id:"proj-grow-capital",slug:"grow-capital",title:"Grow Capital",subtitle:"Digital Gold & Silver Investment Platform",serviceId:"fintech",serviceName:"FinTech Solutions",category:"FinTech",industry:"Digital Finance & Precious Metals",isDemonstrationOrPrototype:!1,statusBadge:"Verified Live Production Platform",thumbnail:"/images/projects/grow-capital/grow-capital-hero.png",heroImage:"/images/projects/grow-capital/grow-capital-hero.png",shortDescription:"A digital precious-metals platform that makes buying, tracking and redeeming gold and silver more accessible.",overview:"Grow Capital is a digital gold and silver investment platform developed to make precious-metal ownership more accessible. Users can purchase fractional quantities of gold and silver starting from ₹10, monitor their real-time holdings, accumulate systematically through savings planners, and choose to liquidate at live market buyback rates or request physical delivery of certified minted bullion coins and bars through integrated bullion infrastructure.",challenge:"Traditional physical precious-metal acquisition across India involves significant structural barriers: high capital minimums for whole bullion coins or bars, opaque jeweller making charges ranging from 8% to 25%, physical custody security concerns, absence of real-time wholesale pricing for retail buyers, and cumbersome buyback verification procedures. Building a digital alternative requires delivering fractional ownership down to four decimal places, streaming millisecond-accurate live market rates, automated KYC verification against national PAN registries, multi-rail instant payment settlement (UPI, net banking, cards), and 100% physical custody backing under institutional trustee oversight.",solution:"Peace Haven architected a modern, high-trust digital precious-metals investment platform directly integrated with Augmont Goldtech for wholesale bullion pricing, order execution, and refinery certification. The platform enables fractional gold and silver micro-investments starting at ₹10, backed 1:1 by physical bullion vaulted in Brinks secure facilities under IDBI Trusteeship Services oversight. Featuring live bullion price locking, systematic savings planners (SIP), seamless UPI checkout, an AI assistant, and doorstep physical coin/bar delivery, Grow Capital delivers institutional-grade bullion accessibility to everyday investors.",architectureHighlights:["Direct integration with Augmont Goldtech API for live 24K 999 gold and 999 fine silver market pricing and order execution","Fractional precious-metal accumulation engine supporting purchases from ₹10 with 4-decimal-place weight precision","100% physical bullion allocation model with storage in Brinks high-security vaults and independent IDBI Trusteeship oversight","Automated digital KYC verification workflow with real-time PAN validation before high-volume bullion settlement","Multi-rail digital payment gateway supporting UPI intent (Google Pay, PhonePe, Paytm), debit/credit cards, and net banking","Systematic Gold & Silver Savings Planner (SIP) calculator enabling disciplined recurring wealth accumulation","Physical redemption and insured logistics pipeline delivering certified tamper-proof minted coins and bars directly to user doorsteps","24/7 Grow Assistant AI chatbot providing instant customer support, transaction guidance, and onboarding assistance"],engineeringCapabilitiesDemonstrated:["Institutional FinTech API integration connecting web interfaces to wholesale bullion infrastructure and liquidity engines","Real-time financial price streaming with dynamic price-lock timers ensuring slippage-free retail order execution","Secure multi-provider architecture coordinating bullion supply (Augmont), custody (Brinks), and trusteeship (IDBI)","High-trust responsive UX combining gold/silver visual aesthetics, light/dark mode theming, and zero-overflow mobile layouts","Regulatory-aligned identity verification flow linking user PAN credentials directly with bullion trading standards"],technologies:["FinTech","Digital Gold","Digital Silver","Investment Platform","Augmont Integration","Brinks Vaults","IDBI Trusteeship","UPI Payments"],resultsOrProjections:[{metric:"₹10",label:"Minimum Investment",detail:"Democratized fractional precious-metal ownership accessible to any investor"},{metric:"24K 999",label:"Certified Bullion Purity",detail:"100% physically backed gold and silver with independent laboratory certification"},{metric:"1:1 Vaulted",label:"Brinks & IDBI Custody",detail:"Fully insured physical bullion vaulted under independent institutional trustee oversight"},{metric:"Instant",label:"Buy, Sell & Doorstep Delivery",detail:"Immediate liquidity to bank accounts or tamper-proof physical coin redemption"}],galleryImages:["/images/projects/grow-capital/grow-capital-hero.png","/images/projects/grow-capital/grow-capital-metals.png","/images/projects/grow-capital/grow-capital-how-it-works.png","/images/projects/grow-capital/grow-capital-calculator.png","/images/projects/grow-capital/grow-capital-security.png","/images/projects/grow-capital/grow-capital-mobile.png"],demoUrl:"https://growcapital.app/",liveUrl:"https://growcapital.app/",seoTitle:"Grow Capital | Digital Gold & Silver Platform | Peace Haven",seoDescription:"Explore Grow Capital, a digital gold and silver platform that makes precious-metal ownership accessible through digital purchases and bullion infrastructure.",implementedFeatures:[{title:"Digital Gold Purchases",description:"Fractional purchase of 24K 999 pure gold by rupee value or gram weight with transparent pricing and live price locks.",tag:"Bullion Core"},{title:"Digital Silver Purchases",description:"Fractional purchase of 999 fine silver starting from ₹10 with instant allocation to user holdings.",tag:"Bullion Core"},{title:"Fractional Purchases from ₹10",description:"Democratized micro-investing allowing users to accumulate precious metals with as little as ₹10 per order.",tag:"Micro-Investing"},{title:"Live Bullion Market Pricing",description:"Real-time market rate synchronization with live buy and sell prices refreshed in real time with price countdown locks.",tag:"Market Feeds"},{title:"Gold & Silver Holdings Portfolio",description:"Transparent digital wallet tracking cumulative gram holdings, current market portfolio valuation, and transaction history.",tag:"Portfolio UX"},{title:"Instant Buy & Sell Functionality",description:"Complete liquidity allowing users to sell vaulted bullion back at live market rates with direct bank payouts.",tag:"Liquidity"},{title:"Gold & Silver Savings Planner (SIP)",description:"Interactive accumulation calculator helping users plan disciplined weekly or monthly precious-metal savings goals.",tag:"Savings Planner"},{title:"Physical Coin & Bar Redemption",description:"Redeem digital holdings for physical certified 24K gold and 999 silver coins/bars with insured doorstep delivery.",tag:"Physical Delivery"},{title:"Multi-Rail Digital Payments",description:"Seamless instant payment checkout supporting UPI intent (Google Pay, PhonePe, Paytm), debit/credit cards, and net banking.",tag:"Payments"},{title:"24/7 Customer Support & Grow Assistant",description:"Integrated conversational assistant providing automated answers to KYC, orders, vaulting, and delivery queries.",tag:"Customer Support"},{title:"Integrated KYC Workflow",description:"Automated identity verification matching full name with PAN records to satisfy regulatory bullion compliance.",tag:"Compliance"}],technicalArchitecture:{layers:[{layer:"Presentation Layer",technology:"Responsive Web UI, CSS Custom Properties, GSAP & Theme Switcher",purpose:"Accessible cross-device customer experience, real-time bullion rate display, and dark/light mode switching"},{layer:"Application & Auth Layer",technology:"REST APIs, Firebase Authentication & App Check",purpose:"Secure customer authentication, session management, and CSRF protection"},{layer:"Bullion Liquidity & Pricing Engine",technology:"Augmont Goldtech Bullion APIs",purpose:"Live wholesale pricing feeds, buy/sell trade execution, order lifecycle, and digital gold account ledgers"},{layer:"Physical Vault & Storage Custody",technology:"Brinks High-Security Insured Vaults",purpose:"100% physically allocated gold and silver bullion storage with comprehensive insurance coverage"},{layer:"Independent Trustee Oversight",technology:"IDBI Trusteeship Services Limited",purpose:"Legal trustee oversight ensuring all physical bullion in Brinks vaults is held exclusively in trust for users"}],flowDiagram:["1. Customer Selection: User selects Gold (24K 999) or Silver (999); enters amount (min ₹10) or weight in grams; locks in live rate","2. Instant Digital Payment: Order dispatches through multi-rail gateway via UPI (Google Pay, PhonePe), card, or net banking","3. Trade Execution & Minting: Augmont executes the bullion buy order; 1:1 allocated physical metal is credited to user wallet","4. Insured Vault Custody: Physical bullion is placed in Brinks security vaults under independent IDBI Trusteeship supervision","5. Liquidation or Physical Redemption: User sells holdings back at live buyback rates OR requests doorstep delivery of minted coins/bars"]},developmentProcess:[{step:"01",title:"Product Architecture & FinTech Scoping",description:"Defining the fractional bullion model, regulatory compliance thresholds, and integration specifications with Augmont."},{step:"02",title:"Precious Metals Visual Design",description:"Crafting the high-trust gold/silver brand system with Deep Bullion Navy, Champagne Gold, and accessible typography."},{step:"03",title:"Live Bullion Pricing Engine Integration",description:"Connecting Augmont streaming price feeds for 24K gold and 999 silver with countdown timer price locking."},{step:"04",title:"Fractional Purchase & Order State Machine",description:"Engineering precision weight-to-rupee calculation engines supporting micro-transactions starting from ₹10."},{step:"05",title:"Multi-Rail Payment Gateway Integration",description:"Integrating seamless UPI intent workflows, debit/credit cards, and net banking with automated webhook confirmations."},{step:"06",title:"Regulatory KYC & PAN Verification Pipeline",description:"Implementing automated identity verification protocols matching PAN records for high-value bullion compliance."},{step:"07",title:"Savings Planner (SIP) & Holdings Portfolio",description:"Developing interactive systematic accumulation calculators and real-time digital asset portfolio dashboards."},{step:"08",title:"Physical Redemption & Production Launch",description:"Deploying end-to-end coin/bar delivery request pipelines and launching the live production platform at growcapital.app."}],liveCta:{heading:"Experience Grow Capital Live",description:"Start buying 24K digital gold and 999 fine silver from ₹10 with live market pricing and 100% vaulted bullion backing.",buttonLabel:"Visit Grow Capital"},publishedAt:"2026-03-20"},{id:"proj-ai-animal-detection",slug:"ai-agricultural-animal-detection",title:"AI-Based Agricultural Animal Detection System",subtitle:"AI-Powered Smart Farming & Crop Protection",serviceId:"robotics",serviceName:"Robotics & Automation",category:"AI & IoT Agricultural Automation",industry:"Agriculture & Smart Farming",isDemonstrationOrPrototype:!0,statusBadge:"Prototype Project",thumbnail:"/images/projects/ai-agricultural-animal-detection/ai-animal-detection-overview.png",heroImage:"/images/projects/ai-agricultural-animal-detection/ai-animal-detection-overview.png",shortDescription:"An intelligent agricultural monitoring system that uses AI-powered animal detection, ESP32-CAM and IoT notifications to help farmers respond to animal intrusion.",overview:"The AI-Based Agricultural Animal Detection & Humane Deterrent System is an intelligent agricultural safety solution designed to detect animals entering farmland and help protect crops from animal intrusion. The system uses an ESP32-CAM and a PIR motion sensor to detect movement and capture images of animals entering agricultural fields. The captured images are processed using an AI-based object detection model to identify the animal species and estimate the detection confidence level. When an animal is identified, the system activates a humane deterrent mechanism designed to encourage the animal to leave the field without causing harm. Simultaneously, a Telegram bot sends an instant notification to the farmer containing the detected animal's name, confidence level, detection status and captured image. The system combines Artificial Intelligence, Computer Vision, Embedded Systems and IoT communication to support crop protection and reduce the need for continuous human monitoring.",challenge:"Animal intrusion poses severe threats to agricultural livelihoods, causing catastrophic crop damage and human-wildlife conflict. Continuous manual monitoring across extensive acreage is physically exhausting, hazardous at night, and impractical for smallholder farmers. Traditional deterrent methods often require intensive human supervision or risk harming wildlife, while farmers remain unaware of intrusion events until severe damage has already occurred.",solution:"Peace Haven engineered an intelligent, multi-tier monitoring prototype that unites passive infrared motion sensing, embedded ESP32-CAM optical capture, AI-driven computer vision inference, automated relay-controlled acoustic deterrents, and instant Telegram bot telemetry. The solution operates autonomously, validating animal presence with confidence scoring before triggering safe deterrents and informing farmers in real time.",architectureHighlights:["PIR sensor interrupt-driven wake cycle minimizing idle power draw in remote field installations","ESP32-CAM optical capture pipeline acquiring high-resolution frames upon perimeter movement triggers","AI object detection workflow identifying wildlife categories (e.g. elephant, boar, deer) with confidence estimation","Dual output dispatch: local humane acoustic/optical deterrent via relay module and remote instant Telegram alert"],engineeringCapabilitiesDemonstrated:["Embedded hardware-software integration across ESP32-CAM, PIR sensor, and relay-switched deterrent modules","Computer vision object detection and multi-class animal classification pipeline with confidence scoring","IoT telemetry integration delivering rich Telegram bot notifications with photo attachments and status metrics","Humane wildlife mitigation engineering designed to protect agricultural boundaries without lethal measures"],technologies:["Artificial Intelligence","Computer Vision","ESP32-CAM","PIR Sensor","IoT","Telegram Bot","Embedded Systems","Relay Control"],resultsOrProjections:[{metric:"94%",label:"Demonstration Confidence",detail:"Benchmarked elephant recognition accuracy in verified prototype tests"},{metric:"< 3s",label:"Alert Dispatch Latency",detail:"From movement detection to Telegram notification delivery"},{metric:"100% Non-Lethal",label:"Humane Deterrent",detail:"Directional acoustic and light deterrents without physical harm"}],galleryImages:["/images/projects/ai-agricultural-animal-detection/ai-animal-detection-overview.png","/images/projects/ai-agricultural-animal-detection/ai-animal-detection-hardware.png","/images/projects/ai-agricultural-animal-detection/ai-animal-detection-telegram.png","/images/projects/ai-agricultural-animal-detection/ai-animal-detection-process.png","/images/projects/ai-agricultural-animal-detection/ai-animal-detection-deterrent.png"],seoTitle:"AI Agricultural Animal Detection System | Robotics & Automation | Peace Haven",seoDescription:"Explore Peace Haven's AI-based agricultural animal detection system, combining ESP32-CAM, computer vision, embedded systems and IoT notifications for smart farming.",implementedFeatures:[{title:"PIR Motion Detection",description:"Passive infrared sensor detecting thermal movement within the monitored perimeter boundary.",tag:"Sensor Tier"},{title:"ESP32-CAM Image Capture",description:"Embedded camera module capturing high-resolution still frames when movement triggers are tripped.",tag:"Vision Tier"},{title:"AI Animal Classification",description:"Object detection model categorizing detected wildlife (elephant, boar, deer) with confidence estimation.",tag:"AI Inference"},{title:"Humane Deterrent Activation",description:"Relay-controlled acoustic buzzer/horn speaker designed to encourage animals to leave without injury.",tag:"Humane Deterrent"},{title:"Telegram Real-Time Alerts",description:"Automated Telegram bot sending instant notifications with detected animal name, confidence, and photo.",tag:"IoT Notification"},{title:"Weatherproof Field Setup",description:"Pole-mounted enclosure accommodating sensor logic, camera lens, and power connectivity for farm perimeters.",tag:"Enclosure & Mount"}],technicalArchitecture:{layers:[{layer:"Sensing & Vision Tier",technology:"PIR Sensor & ESP32-CAM",purpose:"Movement detection, interrupt triggering, and optical frame acquisition"},{layer:"AI Inference Tier",technology:"Computer Vision & Object Detection",purpose:"Species identification, bounding box classification, and confidence score calculation"},{layer:"Local Actuation Tier",technology:"Relay Module & Horn Speaker",purpose:"Safe acoustic and optical deterrent triggering to steer wildlife away from crops"},{layer:"IoT Notification Tier",technology:"Telegram Bot API & Wi-Fi Telemetry",purpose:"Instant mobile alerts dispatching animal details, detection status, and captured imagery to farmers"}],flowDiagram:["1. PIR Motion Sensor detects movement near crop boundary","2. ESP32-CAM wakes and captures visual frame","3. AI Object Detection model analyzes image","4. Animal identified with confidence score (e.g., Elephant 94%, Boar 87%, Deer 82%)","5. Decision: If animal verified, trigger two parallel response actions","   ├── Local: Relay switches on Horn Speaker / Buzzer deterrent","   └── Remote: Telegram Bot sends instant mobile alert with photo to farmer"]},developmentProcess:[{step:"01",title:"Perimeter Motion Detection",description:"PIR sensor detects movement along the crop boundary."},{step:"02",title:"Optical Frame Acquisition",description:"ESP32-CAM captures high-resolution imagery for identification."},{step:"03",title:"AI Object Recognition",description:"Computer vision model processes frame to detect and localize wildlife."},{step:"04",title:"Species & Confidence Estimation",description:"System outputs predicted animal category and confidence level."},{step:"05",title:"Humane Deterrent Triggering",description:"Relay module activates horn speaker to encourage animal retreat."},{step:"06",title:"Instant Telegram Notification",description:"Bot delivers rich alert with animal name, confidence, and image."}],publishedAt:"2026-04-18"},{id:"proj-smart-blind-stick",slug:"smart-blind-stick",title:"Smart Blind Stick",subtitle:"IoT-Based Assistive Mobility System",serviceId:"robotics",serviceName:"Robotics & Automation",category:"Assistive Technology & IoT",industry:"Healthcare Technology & Accessibility",isDemonstrationOrPrototype:!0,statusBadge:"Prototype Project",thumbnail:"/images/projects/smart-blind-stick/smart-blind-stick-overview.png",heroImage:"/images/projects/smart-blind-stick/smart-blind-stick-overview.png",shortDescription:"An intelligent assistive mobility solution integrating ultrasonic obstacle detection, directional vibration feedback, GPS tracking and emergency communication.",overview:"The Smart Blind Stick is an IoT-based assistive mobility system designed to support safer navigation and greater independence for visually impaired individuals. The system integrates embedded systems, ultrasonic sensors, motion detection, GPS tracking and cellular communication to provide obstacle warnings and emergency notifications. Powered by an ESP32-S3 microcontroller, the system coordinates multiple sensors and connected hardware components. Three ultrasonic sensors monitor obstacles in the front, left and right directions. When an obstacle is detected within the configured distance range, the corresponding vibration motor provides directional haptic feedback to alert the user. An MPU6050 accelerometer and gyroscope monitor the stick's movement, orientation and tilt to identify potential fall-related events. When a configured emergency condition is detected, the system uses a GPS module to obtain geographical coordinates and a SIMCom A7670C 4G LTE module to send an emergency SMS containing location information to a designated caretaker. The system also supports cloud data transmission and battery voltage monitoring.",challenge:"Visually impaired individuals face daily navigation obstacles that heighten accident risks and hinder personal mobility. Traditional white canes provide tactile ground feedback but lack multi-directional obstacle advance warning, elevation detection, or emergency location communication. In sudden fall emergencies, individuals may become disoriented or incapacitated without a reliable mechanism to alert family members or caretakers with real-time geographical coordinates.",solution:"Peace Haven engineered an intelligent, IoT-powered assistive mobility prototype built around the ESP32-S3 microcontroller. The system pairs three ultrasonic transducers (front, left, right) with corresponding directional vibration motors to communicate immediate proximity warnings intuitively. An integrated MPU6050 6-axis sensor monitors tilt and motion dynamics to detect fall events, automatically obtaining satellite GPS coordinates and triggering emergency SMS notifications via a SIMCom A7670C 4G LTE cellular module.",architectureHighlights:["Multi-directional obstacle scanning across front, left, and right sectors using ultrasonic sensor timing","Direction-specific haptic vibration feedback providing tactile spatial awareness without audio distraction","6-axis MPU6050 motion and tilt monitoring evaluating sudden deceleration and cane orientation for fall assessment","Autonomous emergency workflow obtaining GPS coordinates and dispatching cellular SMS alerts to designated caretakers"],engineeringCapabilitiesDemonstrated:["Embedded multi-sensor fusion coordinating ultrasonic timing, I2C IMU readings, and UART NMEA GPS telemetry on ESP32-S3","Directional haptic feedback engineering mapping spatial proximity to discrete vibration motor channels","4G LTE cellular AT-command scripting enabling reliable out-of-band emergency SMS transmission with Google Maps links","Assistive device ergonomics designing low-latency, hands-free feedback prioritizing user safety and autonomy"],technologies:["ESP32-S3","IoT","Ultrasonic Sensors","MPU6050","GPS","4G LTE","Embedded Systems","Haptic Feedback"],resultsOrProjections:[{metric:"3-Way",label:"Directional Coverage",detail:"Simultaneous front, left, and right ultrasonic boundary monitoring"},{metric:"< 50ms",label:"Haptic Alert Latency",detail:"Rapid obstacle detection to vibration motor actuation response"},{metric:"4G LTE",label:"Cellular Emergency SMS",detail:"Direct SMS notification with GPS coordinates sent to caretakers"}],galleryImages:["/images/projects/smart-blind-stick/smart-blind-stick-overview.png","/images/projects/smart-blind-stick/smart-blind-stick-prototype.png","/images/projects/smart-blind-stick/smart-blind-stick-enclosure.png","/images/projects/smart-blind-stick/smart-blind-stick-sensors.png","/images/projects/smart-blind-stick/smart-blind-stick-alert.png","/images/projects/smart-blind-stick/smart-blind-stick-process.png"],seoTitle:"Smart Blind Stick | IoT Assistive Mobility System | Peace Haven",seoDescription:"Explore Peace Haven's Smart Blind Stick project, an ESP32-S3 and IoT-based assistive mobility system featuring ultrasonic obstacle detection, directional vibration feedback, GPS and emergency communication.",implementedFeatures:[{title:"Multi-Directional Obstacle Detection",description:"Three ultrasonic sensors monitor front, left, and right sectors to identify nearby physical obstructions.",tag:"Sensory Tier"},{title:"Directional Haptic Feedback",description:"Independent vibration motors buzz according to obstacle direction (left, front, right) for intuitive tactile alerts.",tag:"Haptic Actuation"},{title:"Motion & Orientation Monitoring",description:"MPU6050 6-axis accelerometer and gyroscope monitor stick tilt, movement, and abnormal impact events.",tag:"Motion Processing"},{title:"GPS Location Tracking",description:"Integrated GPS module calculates real-time satellite coordinates (latitude and longitude) for emergency tracking.",tag:"Location Telemetry"},{title:"4G LTE Emergency SMS Alerts",description:"SIMCom A7670C cellular modem dispatches automated emergency SMS with live Google Maps link to caretakers.",tag:"Cellular IoT"},{title:"Battery Voltage Monitoring",description:"Analog voltage divider circuit tracks Li-ion battery health to support low-power awareness.",tag:"Power Management"}],technicalArchitecture:{layers:[{layer:"Environmental Sensing Tier",technology:"Ultrasonic Sensors (x3) & MPU6050 IMU",purpose:"Multi-directional obstacle distance measurement, cane orientation, and fall dynamics"},{layer:"Core Processing Tier",technology:"ESP32-S3 Dual-Core Microcontroller",purpose:"Sensor fusion, distance thresholding, tilt evaluation, and peripheral coordination"},{layer:"Haptic Actuation Tier",technology:"Directional Vibration Motors (x3 + Handle)",purpose:"Direction-specific tactile vibration feedback alerting visually impaired users"},{layer:"Connectivity & Safety Tier",technology:"NEO-6M GPS & SIMCom A7670C 4G LTE",purpose:"Satellite geolocation acquisition and automated emergency SMS notification dispatch"}],flowDiagram:["1. Three Ultrasonic Sensors continuously scan Front, Left, and Right zones","2. ESP32-S3 processes distance time-of-flight and MPU6050 tilt/acceleration","3. Condition A: Obstacle Detected within range -> Activate corresponding Vibration Motor (Left / Front / Right)","4. Condition B: Potential Fall Detected (tilt/impact threshold exceeded)","   ├── ESP32-S3 requests GPS coordinates from satellite module","   └── SIMCom A7670C transmits Emergency SMS with location & Google Maps link to designated caretaker"]},developmentProcess:[{step:"01",title:"Assistive Requirements & Ergonomics",description:"Consulting accessibility guidelines and mapping non-visual directional feedback priorities."},{step:"02",title:"Hardware Architecture & Pinout",description:"Configuring ESP32-S3 GPIO allocations for 3 ultrasonic sensors, I2C IMU, and UART modems."},{step:"03",title:"Multi-Directional Sensor Firmware",description:"Developing non-blocking ultrasonic timing algorithms for front, left, and right proximity detection."},{step:"04",title:"Haptic Feedback Calibration",description:"Tuning vibration pulse frequencies and duty cycles to ensure unmistakable tactile directional alerts."},{step:"05",title:"IMU Motion & Fall Assessment",description:"Programming MPU6050 tilt angles, angular velocity thresholds, and sudden acceleration monitoring."},{step:"06",title:"GPS & 4G Cellular Integration",description:"Implementing NMEA coordinate parsing and SIMCom A7670C AT commands for emergency SMS dispatch."},{step:"07",title:"Battery Management & Housing",description:"Designing compact 3D-printable/modular enclosure and voltage divider monitoring circuit."},{step:"08",title:"Functional Prototype Testing",description:"Validating obstacle detection response, vibration cues, and SMS alert delivery in controlled environments."}],publishedAt:"2026-04-20"},{id:"proj-eb-300-robotic-arm",slug:"eb-300-robotic-arm",title:"EB-300 Robotic Arm",subtitle:"6-Axis Industrial Robotic Manipulator",serviceId:"robotics",serviceName:"Robotics & Automation",category:"Industrial Robotics & Automation",industry:"Manufacturing & Industrial Automation",isDemonstrationOrPrototype:!0,statusBadge:"Prototype Project",thumbnail:"/images/projects/eb-300-robotic-arm/eb-300-overview.png",heroImage:"/images/projects/eb-300-robotic-arm/eb-300-overview.png",shortDescription:"A multi-jointed robotic manipulation system designed to demonstrate coordinated movement, object handling and industrial automation capabilities.",overview:"The EB-300 Robotic Arm is a six-axis robotic manipulation project inspired by industrial robotic systems, designed to perform automated movement and object-handling tasks with flexibility and precision. The project focuses on developing a multi-jointed robotic manipulator capable of moving its end effector through different positions to support applications such as pick-and-place operations, material handling and automated assembly. The robotic arm features a mechanical structure consisting of a base, shoulder, elbow, wrist and end-effector mounting section. Its interconnected joints enable coordinated rotational movements, allowing the arm to reach different positions within its working area. The design incorporates a compact industrial appearance with cylindrical joint housings, connecting links and a stable mounting base. The system can integrate stepper motors or servo motors with an appropriate controller to provide controlled joint movements. By coordinating individual joint movements, the robotic arm can execute programmed motion sequences and perform object-handling operations. The project demonstrates the application of mechanical design, robotics and motion control principles in developing flexible industrial automation solutions.",challenge:"Modern industrial automation and manufacturing workflows demand versatile robotic manipulation to perform repetitive object-handling operations with high repeatability. Traditional dedicated machinery is rigid and costly to retool, while multi-jointed articulated robots must overcome complex spatial positioning, kinematic joint coordination, structural rigidity, and versatile end-effector interfacing across varying payloads without losing positioning stability.",solution:"Peace Haven engineered the EB-300 Robotic Arm, an industrial-inspired 6-axis manipulator prototype designed to demonstrate multi-joint coordinated movement, modular end-effector actuation, and programmable trajectory execution. Featuring six degrees of freedom (Base ±180°, Shoulder ±135°, Elbow ±135°, Wrist 1 ±180°, Wrist 2 ±180°, and Tool Rotation ±360°), an Arduino Mega 2560 control architecture, stepper/servo motor drivers, a 24V power system, and interchangeable tooling (parallel gripper, vacuum suction, magnetic gripper, or custom tool flanges), the system provides a flexible testbed for robotic manipulation concepts.",architectureHighlights:["Six-axis rotational architecture providing 6 degrees of freedom with cylindrical joint housings and rigid structural links","Coordinated kinematic motion control coordinating base, shoulder, elbow, and dual wrist joints across a ~600 mm reach radius","Modular end-effector interface supporting parallel jaws, vacuum suction cups, electromagnets, or specialized tooling","Embedded control architecture powered by Arduino Mega 2560 with dedicated stepper/servo motor drivers and 24V industrial power supply"],engineeringCapabilitiesDemonstrated:["Multi-axis mechanical design integrating compact cylindrical joint housings, bearing assemblies, and structural arm links","Coordinated trajectory execution translating Cartesian spatial targets into individual joint angular movements","Interchangeable end-effector design enabling rapid swapping between mechanical gripping, vacuum suction, and magnetic handling","Embedded pulse-generation and motor driver coordination maintaining smooth multi-joint velocity profiles"],technologies:["Industrial Robotics","6-Axis Manipulation","Motion Control","Mechanical Design","Embedded Systems","Stepper & Servo Actuation","Arduino Mega 2560","Kinematic Positioning"],resultsOrProjections:[{metric:"6-Axis",label:"Degrees of Freedom",detail:"Independent rotational articulation across base, shoulder, elbow, and dual wrist joints"},{metric:"~600 mm",label:"Reach Radius",detail:"Cylindrical workspace envelope with up to ~500 mm vertical operating ceiling"},{metric:"Modular",label:"End-Effector System",detail:"Standardized mounting flange supporting parallel, vacuum, and magnetic grippers"}],galleryImages:["/images/projects/eb-300-robotic-arm/eb-300-overview.png","/images/projects/eb-300-robotic-arm/eb-300-manipulator.png","/images/projects/eb-300-robotic-arm/eb-300-workspace.png","/images/projects/eb-300-robotic-arm/eb-300-views.png","/images/projects/eb-300-robotic-arm/eb-300-dof.png","/images/projects/eb-300-robotic-arm/eb-300-control.png","/images/projects/eb-300-robotic-arm/eb-300-end-effectors.png","/images/projects/eb-300-robotic-arm/eb-300-applications.png"],seoTitle:"EB-300 Robotic Arm | 6-Axis Industrial Robotics | Peace Haven",seoDescription:"Explore Peace Haven's EB-300 six-axis robotic arm project, demonstrating robotic manipulation, mechanical design, coordinated joint movement and industrial automation concepts.",implementedFeatures:[{title:"Six-Axis Joint Articulation",description:"Coordinated rotational movement across Base (±180°), Shoulder (±135°), Elbow (±135°), Wrist 1 (±180°), Wrist 2 (±180°), and End Effector (±360°).",tag:"Kinematic Structure"},{title:"Cylindrical Workspace Reach",description:"Operating envelope providing up to ~500 mm vertical ceiling and ~600 mm horizontal radius for expansive object manipulation.",tag:"Spatial Reach"},{title:"Interchangeable End-Effector Mount",description:"Standardized mechanical interface accommodating dual-jaw parallel grippers, vacuum suction cups, and magnetic handling heads.",tag:"Tooling Interface"},{title:"Microcontroller Actuation Pipeline",description:"Arduino Mega 2560 central controller driving stepper/servo drivers with coordinated step-direction timing.",tag:"Motion Electronics"},{title:"Industrial 24V Power Bus",description:"High-current DC power supply bus providing regulated electrical delivery during simultaneous multi-joint moves.",tag:"Power Architecture"},{title:"Programmed Motion Sequences",description:"Configurable step routines enabling repeatable point-to-point transit and pick-and-place trajectories.",tag:"Automation Control"}],technicalArchitecture:{layers:[{layer:"Supervisory & Command Tier",technology:"Operator Interface & Motion Command Scripting",purpose:"Trajectory generation, waypoint sequencing, and target position formulation"},{layer:"Embedded Motion Controller",technology:"Arduino Mega 2560 Microcontroller",purpose:"Step-direction pulse generation, multi-axis interpolation, and limit monitoring"},{layer:"Actuation & Power Tier",technology:"Dedicated Stepper/Servo Drivers & 24V DC PSU",purpose:"Current regulation, microstepping torque delivery, and electrical isolation"},{layer:"Kinematic & Tooling Tier",technology:"6-DOF Articulated Arm & Modular Grippers",purpose:"Physical spatial positioning, orientation alignment, and payload interaction"}],flowDiagram:["1. Motion Command: System receives trajectory coordinates or configured routine","2. Joint Coordination: Controller computes step counts and angular velocities across all 6 axes","3. Base & Arm Positioning: Joint 1 (Base), Joint 2 (Shoulder), and Joint 3 (Elbow) adjust arm reach","4. Wrist Alignment: Joint 4 (Wrist 1) and Joint 5 (Wrist 2) orient the tool approach angle","5. Object Interaction: Joint 6 (Tool Roll) and mounted End Effector actuate to grip/release object","6. Return / Cycle Repeat: Arm returns to home stance or sequences to the next waypoint"]},developmentProcess:[{step:"01",title:"Kinematic Scoping & DOF Requirements",description:"Defining 6-axis articulated robot geometry, rotational envelopes, and workspace reach radius."},{step:"02",title:"CAD Mechanical Design & Link Sizing",description:"Engineering cylindrical joint housings, ~300 mm upper arm, and ~250 mm forearm linkages."},{step:"03",title:"Actuator Selection & Torque Sizing",description:"Specifying high-torque stepper/servo motors capable of dynamic joint holding and rotational acceleration."},{step:"04",title:"Controller Electronics & Driver Bus",description:"Designing Arduino Mega 2560 driver shielding, step-direction routing, and 24V power distribution."},{step:"05",title:"Firmware Motion Coordination",description:"Writing coordinated multi-axis interpolation routines with acceleration ramping and soft endstops."},{step:"06",title:"Modular End-Effector Interface",description:"Developing quick-change mechanical flange for parallel jaws, suction cups, and magnetic heads."},{step:"07",title:"Workspace & Repeatability Testing",description:"Validating reach envelope (~600 mm radius), multi-view alignment, and smooth trajectory execution."},{step:"08",title:"Prototype Documentation & Applications",description:"Cataloging demonstration workflows for pick-and-place, assembly, and educational robotics."}],publishedAt:"2026-04-22"},{id:"proj-rapid-mi-screening-test",slug:"rapid-mi-screening-test",title:"Rapid MI Screening Test",subtitle:"Cardiac Biomarker Assay Kit for Rapid Detection of Myocardial Infarction",serviceId:"healthcare",serviceName:"Healthcare Solutions",category:"Point-of-Care Diagnostics",industry:"Healthcare & Clinical Diagnostics",isDemonstrationOrPrototype:!0,statusBadge:"Prototype Project",thumbnail:"/images/projects/rapid-mi-screening-test/rapid-mi-test-overview.png",heroImage:"/images/projects/rapid-mi-screening-test/rapid-mi-test-overview.png",shortDescription:"A point-of-care lateral flow immunoassay diagnostic prototype developed for rapid visual detection of cardiac biomarkers in acute myocardial infarction.",overview:"The Rapid MI Screening Test is a point-of-care diagnostic assay prototype developed for rapid, decentralized detection of cardiac biomarkers associated with acute myocardial infarction (heart attack). Engineered using lateral flow immunochromatography principles, the diagnostic kit utilizes colloidal gold nanoparticle-antibody conjugates, a capillary nitrocellulose reaction matrix, and immobilized capture lines to provide definitive visual results within 10 to 15 minutes. By enabling rapid cardiac risk stratification at the point of care—such as in outpatient clinics, triage rooms, and emergency transport units—the project demonstrates the application of biosensor engineering, immunodiagnostics, and clinical workflow optimization to support early cardiovascular intervention.",challenge:'Acute Myocardial Infarction (AMI) requires immediate clinical intervention, as cardiac muscle necrosis progresses rapidly following coronary arterial occlusion ("time is muscle"). Standard laboratory testing methods—such as central hospital ELISA or chemiluminescence immunoassay analyzers—typically require 60 to 120 minutes of turnaround time, venous venipuncture, cold-chain handling, and trained laboratory technicians. Frontline healthcare settings, emergency ambulances, and rural clinics frequently lack immediate access to central laboratories, creating a pressing need for a rapid, low-cost, point-of-care test strip capable of detecting elevated cardiac biomarkers from a single droplet of blood within minutes.',solution:"Peace Haven engineered the Rapid MI Screening Test prototype, a lateral flow chromatographic immunoassay kit designed for frontline cardiac screening. The system features a multi-zone diagnostic strip combining an erythrocyte-filtering sample pad, a gold nanoparticle conjugate pad functionalized with high-affinity anti-cardiac biomarker monoclonal antibodies, a porous nitrocellulose analytical membrane striped with Test (capture) and Control lines, and an absorbent wicking sink. Upon sample addition, capillary migration drives immunocomplex sandwich formation at the Test Line while excess conjugates validate assay integrity at the Control Line, delivering clear visual qualitative readouts in 10–15 minutes without external power or laboratory instruments.",architectureHighlights:["Lateral flow immunochromatographic strip architecture comprising sample pad, conjugate release matrix, nitrocellulose analytical membrane, and cellulose absorbent sink","Colloidal gold nanoparticle-antibody conjugates providing intense chromatic contrast and sub-nanogram/mL analytical sensitivity","Dual-line visual verification with dedicated cardiac biomarker Test Line (sandwich immunocomplex) and secondary Control Line (assay validity)","Rapid 10–15 minute diagnostic window requiring minimal specimen volume (whole blood, serum, or plasma) with no centrifugation or electronic equipment needed"],engineeringCapabilitiesDemonstrated:["Nanoparticle surface chemistry and passive/covalent antibody functionalization for selective biomarker target binding","Capillary fluid dynamics optimization across porous nitrocellulose matrices ensuring uniform flow front without non-specific background","Point-of-care clinical workflow integration bridging frontline patient triage with hospital emergency pathways","High-affinity sandwich immunoassay design minimizing cross-reactivity and false-positive interference"],technologies:["Lateral Flow Immunoassay (LFA)","Point-of-Care Diagnostics","Cardiac Biomarkers","Colloidal Gold Nanoparticles","Monoclonal Antibody Conjugation","Nitrocellulose Capillary Membrane","Biosensor Engineering","Clinical Triage Workflow"],resultsOrProjections:[{metric:"10–15 min",label:"Diagnostic Readout",detail:"Rapid visual interpretation from a single blood drop without laboratory machinery"},{metric:"Dual-Band",label:"Visual Validation",detail:"Independent Test Line (cardiac biomarker) and Control Line (procedural integrity)"},{metric:"Point-of-Care",label:"Decentralized Triage",detail:"Deployable in outpatient clinics, emergency ambulances, and remote healthcare facilities"}],galleryImages:["/images/projects/rapid-mi-screening-test/rapid-mi-test-overview.png","/images/projects/rapid-mi-screening-test/rapid-mi-test-architecture.png","/images/projects/rapid-mi-screening-test/rapid-mi-test-strip.png","/images/projects/rapid-mi-screening-test/rapid-mi-test-conjugate.png","/images/projects/rapid-mi-screening-test/rapid-mi-test-readout.png","/images/projects/rapid-mi-screening-test/rapid-mi-test-control.png"],seoTitle:"Rapid MI Screening Test | Point-of-Care Cardiac Assay | Peace Haven",seoDescription:"Explore Peace Haven's Rapid MI Screening Test prototype: a point-of-care cardiac biomarker lateral flow immunoassay assay kit for early detection of myocardial infarction.",implementedFeatures:[{title:"Lateral Flow Analytical Membrane",description:"High-porosity nitrocellulose membrane calibrated for controlled capillary flow velocity and protein adsorption.",tag:"Reaction Matrix"},{title:"Gold Nanoparticle Conjugate Pad",description:"Functionalized colloidal gold nanoparticles coupled with anti-cardiac biomarker monoclonal antibodies for rapid target binding.",tag:"Nanotechnology"},{title:"Biomarker Sandwich Immunoassay",description:"Specific double-antibody sandwich mechanism producing distinct chromatic test band upon biomarker binding.",tag:"Immunochemistry"},{title:"Built-in Procedural Control Line",description:"Immobilized secondary capture antibodies that validate proper fluid migration and reagent activity on every test.",tag:"Quality Assurance"},{title:"Whole Blood Separation Pad",description:"Pretreated sample application pad engineered to filter cellular blood components while allowing plasma flow.",tag:"Sample Preparation"},{title:"Direct Visual Interpretation",description:"Unequivocal dual-line chromatic readout readable by frontline clinical personnel within 10–15 minutes without instruments.",tag:"Point-of-Care"}],technicalArchitecture:{layers:[{layer:"Sample Delivery & Filtration Tier",technology:"Engineered Sample Pad & Hemolysis Inhibitors",purpose:"Specimen acceptance, erythrocyte retention, and fluid pH buffering"},{layer:"Conjugate & Labeling Tier",technology:"Colloidal Gold Nanoparticle Monoclonal Conjugates",purpose:"Target biomarker recognition and optical signal generation"},{layer:"Analytical Reaction Tier",technology:"Nitrocellulose Membrane Striped with Capture Antibodies",purpose:"Capillary migration, sandwich immunocomplex capture, and control verification"},{layer:"Capillary Absorption & Sink Tier",technology:"High-Capacity Cellulose Absorbent Pad",purpose:"Unidirectional fluid draw, continuous wicking, and backflow prevention"}],flowDiagram:["1. Sample Application: Whole blood or plasma droplet deposited onto the sample application pad with running buffer","2. Conjugate Rehydration: Fluid mobilizes colloidal gold nanoparticle-antibody conjugates which bind cardiac biomarkers","3. Capillary Migration: Capillary forces pull the immunocomplex mixture along the porous nitrocellulose analytical membrane","4. Test Line Capture: Primary immobilized capture antibodies trap biomarker-gold complexes, producing a visible chromatic line","5. Control Line Verification: Secondary capture antibodies bind unreacted gold conjugates, confirming complete capillary transit","6. Readout Interpretation: Excess fluid is sequestered in the absorbent pad; visual inspection performed at 10–15 minutes"]},developmentProcess:[{step:"01",title:"Clinical Biomarker Selection & Specification",description:"Targeting cardiac troponin (cTnI/cTnT) and complementary cardiac necrosis biomarkers for acute triage."},{step:"02",title:"Monoclonal Antibody Pairing & Screening",description:"Screening high-affinity epitope antibody pairs for non-overlapping capture and gold conjugation."},{step:"03",title:"Gold Nanoparticle Synthesis & Functionalization",description:"Synthesizing ~40 nm monodisperse colloidal gold and optimizing antibody conjugation pH and optical density."},{step:"04",title:"Nitrocellulose Striping & Membrane Calibration",description:"Micro-dispensing Test and Control lines on nitrocellulose membranes and calibrating capillary wicking rates."},{step:"05",title:"Sample Pad Pretreatment & Blood Separation",description:"Formulating surfactant and erythrocyte-trapping matrix buffers to ensure smooth whole blood filtration."},{step:"06",title:"Analytical Sensitivity & Cross-Reactivity Testing",description:"Validating detection limits across serial dilutions and verifying specificity against non-target serum proteins."},{step:"07",title:"Thermal Stability & Desiccant Packaging",description:"Conducting accelerated shelf-life studies and hermetic foil pouch packaging with humidity indicators."},{step:"08",title:"Clinical Triage Workflow & Documentation",description:"Compiling instructional guides, visual interpretation charts, and protocol documentation for healthcare providers."}],publishedAt:"2026-04-25"},{id:"proj-ph-homes",slug:"ph-homes",title:"PH Homes",subtitle:"Intelligent Real Estate & Property Platform",serviceId:"web-development",serviceName:"Web Development",category:"Full-Stack Web Application",industry:"Real Estate Technology",isDemonstrationOrPrototype:!0,statusBadge:"Verified Platform Prototype",thumbnail:"/images/projects/ph-homes/ph-homes-homepage.png",heroImage:"/images/projects/ph-homes/ph-homes-homepage.png",shortDescription:"A comprehensive real estate ecosystem combining AI-powered property discovery, interactive maps, property analytics, agent workflows and a home-services marketplace.",overview:"PH Homes is a full-stack real estate platform designed for the US property market, bringing property discovery, intelligent search, real estate analytics, communication and home services into one unified digital ecosystem. Built using React.js, Node.js, Express.js and MongoDB, the platform supports seven user roles: buyers, renters, agents, service providers, reviewers, concierge staff and administrators. Buyers and renters can discover properties through interactive maps or AI-powered natural-language search. They can explore property listings with PHWorth valuations, investment analysis, neighborhood insights, commute information and city-level market analytics. The platform also provides saved properties, saved searches with email alerts, side-by-side comparisons, collaborative co-shopping groups and roommate matching to simplify the property discovery process. Integrated inquiries, viewing requests, rental applications, real-time messaging and live notifications connect buyers and renters with agents. Agents can publish and manage property listings through a verification workflow that includes photo uploads and ownership-document review before listings are made public. Dedicated dashboards support lead management and property-level analytics. PH Homes also includes a home-services marketplace where homeowners can request services, receive quotes from providers serving their ZIP codes, hire professionals and submit reviews. Stripe integration supports subscription plans, lead credits and featured listings. A centralized administration console provides tools for account management, listing moderation, review moderation, refunds and audit logging. The platform also incorporates authentication, validation, security controls, error monitoring, privacy-aware logging and automated testing. PH Homes demonstrates how modern full-stack engineering can combine multiple real estate workflows into a connected, scalable and user-focused platform.",challenge:"The US residential real estate landscape is traditionally fractured across siloed platforms: buyers browse MLS search portals, renters submit unstandardized applications, agents juggle third-party CRMs and spreadsheet lead trackers, and homeowners search separate local classifieds for home maintenance contractors. Unifying seven distinct user personas (buyers, renters, agents, service providers, reviewers, concierge staff, and administrators) within a single secure ecosystem requires resolving complex challenges in multi-tier role authorization, real-time bidirectional communication, geospatial map querying, high-volume image processing, listing fraud prevention through structured verification workflows, and reliable payment integration.",solution:"Peace Haven engineered PH Homes as an integrated full-stack MERN (React 18, Vite, Node.js, Express, MongoDB) platform designed specifically for property discovery, transaction coordination, and local home services. The platform combines Google Maps JavaScript API with polygon drawing tools and AI-driven natural-language search for intelligent property matching. An end-to-end listing verification pipeline mandates ownership documentation and high-resolution photo review before public indexing. A dedicated agent CRM offers real-time Kanban pipelines, lead scoring, and automated task tracking. Bi-directional Socket.IO integration delivers instant messaging and push notifications across parties, while Stripe powers subscription tiers, lead credits, and featured property boosts.",architectureHighlights:["React 18 single-page application built with Vite and Tailwind CSS featuring glassmorphism search interfaces, interactive filter drawers, and responsive design across all viewports","Modular Node.js and Express RESTful API with route-level Zod validation schemas, rate limiting, and centralized error handling middlewares","MongoDB database with Mongoose schemas leveraging 2dsphere geospatial indexing for radius and polygon property queries","Interactive Google Maps JavaScript API integration featuring Advanced Markers, vector styling, and custom boundary polygon search filtering","Bi-directional Socket.IO WebSocket infrastructure for instantaneous chat messaging, viewing request alerts, and live agent lead delivery","Stripe integration supporting multi-tiered agent subscriptions, lead credit balances, and featured property listing upgrades","Multi-stage listing review workflow requiring authorized staff approval of property photos and ownership documentation prior to public visibility","Continuous Integration pipeline in GitHub Actions validating 265+ automated unit and integration tests across 10 Vitest backend suites"],engineeringCapabilitiesDemonstrated:["Multi-tenant role-based access control (RBAC) securely segregating 7 distinct user roles across unified API endpoints","Geospatial search and property clustering combining Google Maps JS API, vector overlays, and MongoDB geospatial query operators","Real-time bidirectional event coordination through Socket.IO for messaging, notification streams, and pipeline status updates","Automated testing rigor with 265 passing unit and integration tests covering auth, listings, leads, CRM, reviews, and admin operations","Secure payment processing with Stripe webhook verification, transaction idempotency, and automated credit balance management","Enterprise security hygiene including bcrypt password hashing, JWT authentication, HTTP-only cookies, Helmet headers, CORS policies, and sanitized logging"],technologies:["React.js","Node.js","Express.js","MongoDB","AI-Powered Search","Socket.IO","Stripe","Google Maps API","Tailwind CSS","Vite","Zod","JWT","Docker","Vitest"],resultsOrProjections:[{metric:"7 Roles",label:"Unified Ecosystem",detail:"Buyers, renters, agents, service providers, reviewers, concierge & admins"},{metric:"265+ Tests",label:"Automated Backend Tests",detail:"10 passing Vitest test suites with 100% CI pass rate in GitHub Actions"},{metric:"Real-Time",label:"Socket.IO Architecture",detail:"Instant messaging, live viewing alerts & CRM lead notifications"},{metric:"Full-Stack",label:"MERN & Geospatial",detail:"React 18, Express, MongoDB 2dsphere indexes & Google Maps API"}],galleryImages:["/images/projects/ph-homes/ph-homes-homepage.png","/images/projects/ph-homes/ph-homes-agent-dashboard.png","/images/projects/ph-homes/ph-homes-lead-pipeline.png","/images/projects/ph-homes/ph-homes-analytics.png","/images/projects/ph-homes/ph-homes-admin-dashboard.png","/images/projects/ph-homes/ph-homes-agent-performance.png","/images/projects/ph-homes/ph-homes-lead-details.png","/images/projects/ph-homes/ph-homes-sell-valuation.png","/images/projects/ph-homes/ph-homes-callback-inquiry.png","/images/projects/ph-homes/ph-homes-mobile-pipeline.png"],seoTitle:"PH Homes – Full-Stack Real Estate Platform | Case Study | Peace Haven",seoDescription:"Explore PH Homes, an intelligent full-stack real estate platform developed with React, Node.js, Express, and MongoDB featuring AI property search, maps, CRM, and home services.",implementedFeatures:[{title:"AI-Powered Property Discovery",description:"Natural-language property search allowing users to query homes by conversational preferences, budget ranges, and lifestyle parameters with smart result ranking.",tag:"AI & Search"},{title:"Interactive Property Maps",description:"Google Maps JavaScript API integration featuring dynamic price markers, vector map overlays, zoom clustering, and freehand polygon boundary filtering.",tag:"Geospatial Maps"},{title:"PHWorth Property Intelligence",description:"Algorithmic valuation interface displaying estimated property value, investment yield projections, historical pricing trajectories, and comparative market metrics.",tag:"Valuation & Analytics"},{title:"Neighborhood & Market Insights",description:"Google Places-powered point-of-interest discovery, school zone ratings, transit commute times, and city-level real estate trend analytics.",tag:"Location Intelligence"},{title:"Property Discovery Tools",description:"Saved favorite properties, saved custom search queries with automated email notifications, side-by-side comparison tables, co-shopping groups, and roommate matching.",tag:"Discovery Tools"},{title:"Buyer & Renter Workflows",description:"Integrated property inquiries, automated tour/viewing appointment scheduling, digital rental applications with document uploads, and live status tracking.",tag:"Transactions"},{title:"Real-Time Communication",description:"Socket.IO bi-directional WebSocket channels connecting buyers, renters, and listing agents with instantaneous messaging, read receipts, and live push notifications.",tag:"Real-Time Messaging"},{title:"Agent Management Dashboard",description:"Dedicated CRM workstation for real estate professionals featuring Kanban lead pipelines, listing inventory management, performance analytics, and lead scoring.",tag:"Agent Workstation"},{title:"Home-Services Marketplace",description:"Localized contractor marketplace where homeowners post service requests, receive competing quotes from ZIP-code-verified professionals, hire, and post reviews.",tag:"Service Marketplace"},{title:"Payment & Subscription Management",description:"Stripe payment integration supporting agent monthly subscription tiers, lead credit top-ups, and premium featured listing advertising placements.",tag:"Monetization & Billing"}],technicalArchitecture:{layers:[{layer:"Presentation Layer",technology:"React 18, Vite, Tailwind CSS, Lucide Icons, Glassmorphic UI",purpose:"Responsive cross-device client interfaces, interactive state management, and real-time dashboard visualization"},{layer:"API & Application Layer",technology:"Node.js, Express.js, Zod Validation, JWT Auth, Helmet, CORS",purpose:"RESTful API routing, role authorization, request schema validation, and centralized exception handling"},{layer:"Real-Time Event Layer",technology:"Socket.IO WebSocket Engine",purpose:"Bi-directional live communication for direct messaging, viewing alerts, and immediate agent lead delivery"},{layer:"Data & Persistence Layer",technology:"MongoDB, Mongoose ODM, 2dsphere Geospatial Indexes",purpose:"Document persistence, ACID transactions, coordinate indexing, and compound querying across listings and leads"},{layer:"External Integrations Tier",technology:"Stripe API, Google Maps JS API, Google Places, Cloudinary, OAuth 2.0",purpose:"Payment collection, mapping/geocoding, CDN asset optimization, and third-party federated authentication"}],flowDiagram:["1. Client Request & Auth: Client initiates session via JWT or OAuth 2.0; Express middleware verifies token and evaluates RBAC permissions for 7 supported roles","2. Property Query & Discovery: User issues natural-language search or map polygon query; backend executes MongoDB 2dsphere geospatial search with compound filter indexes","3. Agent Listing Submission: Agent creates listing, uploading high-res photos and proof-of-ownership documents via Multer/Cloudinary to a secured staging queue","4. Verification Pipeline: Authorized staff reviewer inspects title documents and photos; upon approval, listing status transitions to active and becomes publicly discoverable","5. Lead Engagement & Real-Time Chat: Buyer submits inquiry or viewing request; Socket.IO instantly notifies agent CRM dashboard and opens secure direct chat thread","6. Marketplace & Billing: Homeowners submit ZIP-based service jobs; providers respond with quotes; agents manage Stripe subscriptions and purchase lead credits"]},developmentProcess:[{step:"01",title:"Domain Modeling & Role Matrix Specification",description:"Mapped 7 distinct user personas (buyers, renters, agents, service providers, reviewers, concierge, admins) and established granular permission gates."},{step:"02",title:"Geospatial Schema & Index Optimization",description:"Designed MongoDB Mongoose schemas with 2dsphere geospatial coordinates, property attribute filters, and composite search indexes."},{step:"03",title:"Interactive Map & UI Component Engineering",description:"Integrated Google Maps JavaScript API with custom pin markers, clustering algorithms, and freehand polygon drawing capabilities."},{step:"04",title:"Listing Verification & Moderation Pipeline",description:"Engineered a multi-stage review workflow requiring document upload, authorized staff inspection, and audit-logged approval before public publishing."},{step:"05",title:"Real-Time Socket.IO Messaging Architecture",description:"Built WebSocket event handlers for direct buyer-agent conversations, viewing request updates, and real-time lead notification delivery."},{step:"06",title:"Agent CRM & Pipeline Management System",description:"Implemented Kanban lead progression, contact timelines, activity logging, lead scoring algorithms, and conversion analytics."},{step:"07",title:"Stripe Monetization & Service Marketplace",description:"Integrated Stripe Checkout and Webhooks for agent recurring subscriptions, lead credit balances, and ZIP-code contractor quotes."},{step:"08",title:"Automated Vitest Suite & CI Pipeline",description:"Authored 265+ unit and integration tests across 10 suites validating security, authentication, CRUD operations, and pipeline workflows in GitHub Actions."}],liveCta:{heading:"Interested in Custom Real Estate Technology?",description:"Whether you are looking to build a multi-tenant property portal, an intelligent real estate CRM, or a location-based marketplace, Peace Haven engineers secure, scalable, and responsive web platforms.",buttonLabel:"Inquire About Web Development"},publishedAt:"2026-03-10"}];export{e as p};
